package com.ashkan.hotel;

import java.io.IOException;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Local restaurant and cafe ordering service, optionally consuming one linked inventory SKU per menu item. */
public final class RestaurantService {
    public enum OrderStatus { OPEN, PREPARING, SERVED, PAID, CANCELLED }
    public record MenuItem(String code, String name, String category, BigDecimal price, String stockSku, BigDecimal stockPerServing, boolean available) {
        public MenuItem { code=req(code); name=req(name); category=clean(category); price=nonNegative(price); stockSku=clean(stockSku); stockPerServing=nonNegative(stockPerServing); if(stockSku.isBlank() && stockPerServing.signum()>0) throw new IllegalArgumentException("Stock SKU is required when recipe quantity is set"); }
    }
    public record OrderLine(String code, String name, int quantity, BigDecimal unitPrice) { public BigDecimal total(){return unitPrice.multiply(BigDecimal.valueOf(quantity));} }
    public record Order(long id, String table, String guest, LocalDateTime createdAt, OrderStatus status, List<OrderLine> lines, BigDecimal total) { public Order { lines=List.copyOf(lines); } }
    private final Path file; private final Clock clock; private final InventoryService inventory;
    private final Map<String,MenuItem> menu=new TreeMap<>(String.CASE_INSENSITIVE_ORDER); private final List<Order> orders=new ArrayList<>(); private long nextId=1;
    public RestaurantService(InventoryService inventory){this(Path.of(System.getProperty("user.home"),".ashkan-hotelsphere","restaurant.tsv"),Clock.systemDefaultZone(),inventory);}
    public RestaurantService(Path file,Clock clock,InventoryService inventory){this.file=Objects.requireNonNull(file);this.clock=Objects.requireNonNull(clock);this.inventory=Objects.requireNonNull(inventory);try{Files.createDirectories(file.toAbsolutePath().getParent());if(Files.exists(file))load();}catch(IOException e){throw new IllegalStateException("Cannot load restaurant data",e);}}
    private static String clean(String s){return s==null?"":s.strip();} private static String req(String s){String v=clean(s);if(v.isBlank())throw new IllegalArgumentException("Required value is missing");return v;}
    private static BigDecimal nonNegative(BigDecimal n){Objects.requireNonNull(n);if(n.signum()<0)throw new IllegalArgumentException("Amount cannot be negative");return n.stripTrailingZeros();}
    public synchronized void saveMenuItem(MenuItem item)throws IOException{MenuItem old=menu.put(item.code(),item);try{persist();}catch(IOException e){if(old==null)menu.remove(item.code());else menu.put(old.code(),old);throw e;}}
    public synchronized List<MenuItem> menu(){return List.copyOf(menu.values());} public synchronized List<Order> orders(){return orders.stream().sorted(Comparator.comparingLong(Order::id).reversed()).toList();}
    public synchronized Order placeOrder(String table,String guest,Map<String,Integer> requested)throws IOException{
        if(requested==null||requested.isEmpty())throw new IllegalArgumentException("Order must contain at least one item");
        List<OrderLine> lines=new ArrayList<>();for(var e:requested.entrySet()){MenuItem m=menu.get(e.getKey());if(m==null||!m.available())throw new IllegalArgumentException("Menu item unavailable: "+e.getKey());if(e.getValue()==null||e.getValue()<=0)throw new IllegalArgumentException("Quantity must be positive");lines.add(new OrderLine(m.code(),m.name(),e.getValue(),m.price()));}
        List<InventoryService.Movement> consumed=new ArrayList<>();try{for(OrderLine line:lines){MenuItem m=menu.get(line.code());if(!m.stockSku().isBlank()&&m.stockPerServing().signum()>0)consumed.add(inventory.consume(m.stockSku(),m.stockPerServing().multiply(BigDecimal.valueOf(line.quantity())),"REST-ORDER", "Restaurant order item "+line.code()));}}catch(Exception ex){rollbackInventory(consumed);if(ex instanceof RuntimeException r)throw r;throw new IllegalStateException(ex);}
        BigDecimal total=lines.stream().map(OrderLine::total).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);Order order=new Order(nextId++,req(table),clean(guest),LocalDateTime.now(clock),OrderStatus.OPEN,lines,total);orders.add(order);try{persist();}catch(IOException e){orders.remove(order);nextId--;rollbackInventory(consumed);throw e;}return order;
    }
    private void rollbackInventory(List<InventoryService.Movement> movements){for(int i=movements.size()-1;i>=0;i--){InventoryService.Movement m=movements.get(i);try{inventory.adjust(m.sku(),m.quantity().abs(),"REST-ROLLBACK","Rollback failed restaurant order");}catch(Exception ignored){}}}
    public synchronized void updateStatus(long id,OrderStatus status)throws IOException{int idx=index(id);Order old=orders.get(idx);if(old.status()==OrderStatus.CANCELLED||old.status()==OrderStatus.PAID)throw new IllegalStateException("Closed order cannot be changed");if(status==OrderStatus.CANCELLED){for(OrderLine l:old.lines()){MenuItem m=menu.get(l.code());if(m!=null&&!m.stockSku().isBlank()&&m.stockPerServing().signum()>0)inventory.adjust(m.stockSku(),m.stockPerServing().multiply(BigDecimal.valueOf(l.quantity())),"REST-CANCEL","Cancelled order "+id);}}orders.set(idx,new Order(old.id(),old.table(),old.guest(),old.createdAt(),status,old.lines(),old.total()));try{persist();}catch(IOException e){orders.set(idx,old);throw e;}}
    private int index(long id){for(int i=0;i<orders.size();i++)if(orders.get(i).id()==id)return i;throw new IllegalArgumentException("Unknown order: "+id);}
    public synchronized BigDecimal salesTotal(){return orders.stream().filter(o->o.status()!=OrderStatus.CANCELLED).map(Order::total).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public synchronized String ordersCsv(){StringBuilder b=new StringBuilder("OrderId,Table,Guest,CreatedAt,Status,Items,Total\n");for(Order o:orders())b.append(o.id()).append(',').append(csv(o.table())).append(',').append(csv(o.guest())).append(',').append(o.createdAt()).append(',').append(o.status()).append(',').append(csv(o.lines().stream().map(l->l.code()+" - "+l.name()+" x"+l.quantity()).reduce((a,c)->a+"; "+c).orElse(""))).append(',').append(o.total()).append('\n');return b.toString();}
    private static String csv(String s){return "\""+clean(s).replace("\"","\"\"")+"\"";} private static String enc(String s){return Base64.getEncoder().encodeToString(clean(s).getBytes(StandardCharsets.UTF_8));}private static String dec(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
    private void persist()throws IOException{Path tmp=Files.createTempFile(file.toAbsolutePath().getParent(),"restaurant-",".tmp");try{List<String> rows=new ArrayList<>();for(MenuItem m:menu.values())rows.add(String.join("\t","I",enc(m.code()),enc(m.name()),enc(m.category()),m.price().toPlainString(),enc(m.stockSku()),m.stockPerServing().toPlainString(),Boolean.toString(m.available())));for(Order o:orders){StringBuilder lines=new StringBuilder();for(OrderLine l:o.lines()){if(lines.length()>0)lines.append(';');lines.append(enc(l.code())).append(':').append(enc(l.name())).append(':').append(l.quantity()).append(':').append(l.unitPrice().toPlainString());}rows.add(String.join("\t","O",Long.toString(o.id()),enc(o.table()),enc(o.guest()),o.createdAt().toString(),o.status().name(),enc(lines.toString()),o.total().toPlainString()));}Files.write(tmp,rows,StandardCharsets.UTF_8);try{Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
    private void load()throws IOException{for(String row:Files.readAllLines(file,StandardCharsets.UTF_8)){String[] f=row.split("\\t",-1);try{if(f.length==8&&f[0].equals("I")){MenuItem m=new MenuItem(dec(f[1]),dec(f[2]),dec(f[3]),new BigDecimal(f[4]),dec(f[5]),new BigDecimal(f[6]),Boolean.parseBoolean(f[7]));menu.put(m.code(),m);}else if(f.length==8&&f[0].equals("O")){List<OrderLine> ls=new ArrayList<>();String packed=dec(f[6]);if(!packed.isBlank())for(String x:packed.split(";")){String[] p=x.split(":",-1);ls.add(new OrderLine(dec(p[0]),dec(p[1]),Integer.parseInt(p[2]),new BigDecimal(p[3])));}Order o=new Order(Long.parseLong(f[1]),dec(f[2]),dec(f[3]),LocalDateTime.parse(f[4]),OrderStatus.valueOf(f[5]),ls,new BigDecimal(f[7]));orders.add(o);nextId=Math.max(nextId,o.id()+1);}}catch(RuntimeException ignored){}}}
}
